function mkvTokens(text){
  var s=String(text||'').replace(/\s+/g,' ').trim();
  if(!s) return [];
  var hasCjk=/[\u4e00-\u9fff]/.test(s);
  if(hasCjk) return s.replace(/ /g,'').split('');
  return s.split(' ');
}
function mkvBuild(text, order){
  order=Math.max(1, Math.min(5, Math.floor(order)||1));
  var toks=mkvTokens(text);
  if(toks.length<=order) return { error:'语料太短（至少需要 '+(order+1)+' 个 token）' };
  var chain={}, starts=[];
  for(var i=0;i+order<toks.length;i++){
    var key=toks.slice(i,i+order).join('\u0001');
    if(!chain[key]) chain[key]=[];
    chain[key].push(toks[i+order]);
    if(i===0 || /[.!?。！？]$/.test(toks[i-1])) starts.push(key);
  }
  if(!starts.length) starts.push(toks.slice(0,order).join('\u0001'));
  var cjk=/[\u4e00-\u9fff]/.test(toks.join(''));
  return { error:null, chain:chain, starts:starts, order:order, cjk:cjk };
}
function mkvGen(model, maxLen, rng){
  if(model.error) return '';
  rng = rng || Math.random;
  maxLen=Math.max(1, Math.floor(maxLen)||50);
  var key=model.starts[Math.floor(rng()*model.starts.length)];
  var out=key.split('\u0001');
  while(out.length<maxLen){
    var opts=model.chain[key];
    if(!opts || !opts.length) break;
    var next=opts[Math.floor(rng()*opts.length)];
    out.push(next);
    key=out.slice(out.length-model.order).join('\u0001');
  }
  return out.join(model.cjk?'':' ');
}
function mkvStats(model){
  if(model.error) return { keys:0, edges:0 };
  var keys=0, edges=0;
  for(var k in model.chain){ keys++; edges+=model.chain[k].length; }
  return { keys:keys, edges:edges };
}
function mkvSeedRng(seed){
  var t=seed>>>0;
  return function(){
    t += 0x6D2B79F5;
    var r=Math.imul(t ^ (t>>>15), 1|t);
    r = (r + Math.imul(r ^ (r>>>7), 61|r)) ^ r;
    return ((r ^ (r>>>14))>>>0)/4294967296;
  };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { mkvTokens:mkvTokens, mkvBuild:mkvBuild, mkvGen:mkvGen, mkvStats:mkvStats, mkvSeedRng:mkvSeedRng };
}
if (typeof window !== 'undefined') {
  window.MarkovForgePure = { mkvTokens:mkvTokens, mkvBuild:mkvBuild, mkvGen:mkvGen, mkvStats:mkvStats, mkvSeedRng:mkvSeedRng };
}
